1: /**
2:  * weather-card.js — dependency-free module that renders weather data into
3:  * a friendly card UI.
4:  *
5:  * Public API
6:  * ----------
7:  *  renderWeatherCard(city)              -> string   (HTML for one card)
8:  *  renderWeatherGrid(cities)            -> string   (HTML for a grid of cards)
9:  *  renderWeatherGridToElement(el, cities) -> Element|null
10:  *  injectStyles()                       -> void     (injects the card CSS, browser only)
11:  *
12:  * `city` shape (missing fields are gracefully omitted):
13:  *   {
14:  *     city: 'Tokyo',                     // required
15:  *     country: 'JP',                     // optional
16:  *     temp: 22,                          // required
17:  *     unit: '°C',                        // optional ('C' | 'F' | '°C' | '°F'), default '°C'
18:  *     feelsLike: 20,                     // optional
19:  *     condition: 'partly-cloudy',        // code, icon name, or free text ('light rain'…)
20:  *     icon: 'cloudy',                    // alternative to `condition`
21:  *     description: 'Mostly sunny',       // optional human-readable description
22:  *     humidity: 65,                      // optional, %
23:  *     windKmh: 12,                       // optional
24:  *     windDirection: 'NW',               // optional
25:  *     high: 25, low: 17,                 // optional
26:  *     time: '14:18',                     // optional display time
27:  *     hourly: [{ time: '15:00', temp: 22, condition: 'cloudy' }]
28:  *   }
29:  */
30: 
31: const ICONS = {
32:   clear:           { emoji: '☀️', label: 'Sunny' },
33:   'clear-night':   { emoji: '🌙', label: 'Clear night' },
34:   'partly-cloudy': { emoji: '🌤️', label: 'Partly cloudy' },
35:   cloudy:          { emoji: '☁️', label: 'Cloudy' },
36:   overcast:        { emoji: '☁️', label: 'Overcast' },
37:   fog:             { emoji: '🌫️', label: 'Foggy' },
38:   drizzle:         { emoji: '🌦️', label: 'Drizzle' },
39:   rain:            { emoji: '🌧️', label: 'Rainy' },
40:   'heavy-rain':    { emoji: '🌧️', label: 'Heavy rain' },
41:   thunderstorm:    { emoji: '⛈️', label: 'Thunderstorm' },
42:   snow:            { emoji: '❄️', label: 'Snowy' },
43:   sleet:           { emoji: '🌨️', label: 'Sleet' },
44: };
45: 
46: const GRADIENTS = {
47:   clear:           'linear-gradient(135deg, #ffd166, #f77f00)',
48:   'clear-night':   'linear-gradient(135deg, #1e3a5f, #0d1b2a)',
49:   'partly-cloudy': 'linear-gradient(135deg, #90caf9, #4fc3f7)',
50:   cloudy:          'linear-gradient(135deg, #b0bec5, #78909c)',
51:   overcast:        'linear-gradient(135deg, #90a4ae, #546e7a)',
52:   fog:             'linear-gradient(135deg, #eceff1, #b0bec5)',
53:   drizzle:         'linear-gradient(135deg, #78909c, #546e7a)',
54:   rain:            'linear-gradient(135deg, #546e7a, #263238)',
55:   'heavy-rain':    'linear-gradient(135deg, #37474f, #1a2228)',
56:   thunderstorm:    'linear-gradient(135deg, #455a64, #1a2228)',
57:   snow:            'linear-gradient(135deg, #e0f7fa, #b2dfdb)',
58:   sleet:           'linear-gradient(135deg, #cfd8dc, #90a4ae)',
59: };
60: 
61: const LIGHT = ['clear', 'partly-cloudy', 'cloudy', 'overcast', 'fog', 'drizzle', 'snow', 'sleet'];
62: 
63: const FALLBACK = { emoji: '☁️', label: 'Weather' };
64: 
65: const KEYWORD_RULES = [
66:   { re: /thunder|lightning|storm/, name: { code: 'thunderstorm', emoji: '⛈️', label: 'Thunderstorm' } },
67:   { re: /snow|sleet/,              name: { code: 'snow', ...ICONS.snow } },
68:   { re: /rain|drizzle/,           name: { code: 'rain', ...ICONS.rain } },
69:   { re: /fog|mist|haze/,          name: { code: 'fog', ...ICONS.fog } },
70:   { re: /cloud|overcast/,         name: { code: 'cloudy', ...ICONS.cloudy } },
71:   { re: /clear|sunny|sun/,        name: { code: 'clear', ...ICONS.clear } },
72: ];
73: 
74: function esc(v) {
75:   return String(v ?? '').replace(/[&<>"']/g, (ch) => ({
76:     '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
77:   }[ch]));
78: }
79: 
80: export function unitOf(city) {
81:   const u = String(city.unit ?? city.tempUnit ?? 'C').replace(/°/g, '').toUpperCase();
82:   return u === 'F' ? '°F' : '°C';
83: }
84: 
85: export function resolveCondition(city) {
86:   const raw = String(
87:     city.condition ?? city.icon ?? city.weather?.condition ?? city.weather?.icon ?? 'clear'
88:   ).toLowerCase().replace(/\s+/g, '-');
89:   if (ICONS[raw]) return { code: raw, ...ICONS[raw] };
90:   for (const rule of KEYWORD_RULES) {
91:     if (rule.re.test(raw)) return { code: rule.name.code, ...rule.name };
92:   }
93:   return { code: 'cloudy', ...FALLBACK };
94: }
95: 
96: function themeFor(code) {
97:   const light = LIGHT.includes(code);
98:   return {
99:     text: light ? '#1a202c' : '#f7fafc',
100:     chip: light ? 'rgba(255, 255, 255, 0.30)' : 'rgba(255, 255, 255, 0.14)',
101:   };
102: }
103: 
104: function statRows(city) {
105:   const rows = [
106:     { label: 'Feels like', value: city.feelsLike != null ? `${esc(city.feelsLike)}${unitOf(city)}` : null },
107:     { label: 'Humidity',   value: city.humidity   != null ? `${esc(city.humidity)}%` : null },
108:     { label: 'Wind',       value: city.windKmh    != null
109:       ? `${esc(city.windKmh)} km/h${city.windDirection ? ' ' + esc(city.windDirection) : ''}`
110:       : null },
111:     { label: 'Today',      value: city.high != null && city.low != null
112:       ? `${esc(city.high)}° / ${esc(city.low)}°` : null },
113:   ];
114:   return rows
115:     .filter((r) => r.value != null)
116:     .map((r) => `<div class="wc-stat"><span class="wc-stat-label">${r.label}</span><span class="wc-stat-value">${r.value}</span></div>`)
117:     .join('');
118: }
119: 
120: function hourlyRow(hourly, unit) {
121:   if (!Array.isArray(hourly) || hourly.length === 0) return '';
122:   const items = hourly
123:     .map((h) => {
124:       const cond = resolveCondition(h);
125:       const t = h.temp != null ? `${esc(h.temp)}${unit}` : '';
126:       return `<div class="wc-hour"><span class="wc-hour-time">${esc(h.time ?? '')}</span><span class="wc-hour-icon" aria-hidden="true">${cond.emoji}</span><span class="wc-hour-temp">${t}</span></div>`;
127:     })
128:     .join('');
129:   return `<div class="wc-hourly" aria-label="Hourly forecast">${items}</div>`;
130: }
131: 
132: export function renderWeatherCard(city) {
133:   const unit = unitOf(city);
134:   const cond = resolveCondition(city);
135:   const label = esc(city.description ?? cond.label);
136:   const theme = themeFor(cond.code);
137:   const gradient = GRADIENTS[cond.code] ?? GRADIENTS.cloudy;
138: 
139:   const sub = city.country != null
140:     ? `<span class="wc-sub">${esc(city.country)}</span>`
141:     : '';
142:   const time = city.time != null ? `<span class="wc-time">${esc(city.time)}</span>` : '';
143: 
144:   const header = `<div class="wc-header"><div class="wc-location"><span class="wc-city">${esc(city.city)}</span>${sub}</div>${time}</div>`;
145: 
146:   const main = `<div class="wc-main"><span class="wc-icon" aria-hidden="true">${cond.emoji}</span><div class="wc-temp"><span class="wc-temp-value">${esc(city.temp ?? '–')}</span><span class="wc-temp-unit">${unit}</span></div><p class="wc-condition">${label}</p></div>`;
147: 
148:   const stats = statRows(city);
149:   const hourlyHtml = hourlyRow(city.hourly, unit);
150: 
151:   return `<article class="wc" style="--wc-bg:${gradient}; --wc-text:${theme.text}; --wc-chip:${theme.chip}">${header}${main}${stats ? `<div class="wc-stats">${stats}</div>` : ''}${hourlyHtml}</article>`;
152: }
153: 
154: export function renderWeatherGrid(cities) {
155:   const list = Array.isArray(cities) ? cities : [cities];
156:   return `<div class="wc-grid" role="list">${list.map(renderWeatherCard).join('')}</div>`;
157: }
158: 
159: export function renderWeatherGridToElement(container, cities) {
160:   injectStyles();
161:   if (container) container.innerHTML = renderWeatherGrid(cities);
162:   return container;
163: }
164: 
165: export function injectStyles() {
166:   if (typeof document === 'undefined') return;
167:   if (document.getElementById('weather-card-style')) return;
168:   const style = document.createElement('style');
169:   style.id = 'weather-card-style';
170:   style.textContent = CARD_CSS;
171:   document.head.appendChild(style);
172: }
173: 
